<script setup lang="ts">
import { ref } from 'vue'
const variant=ref('primary')
const size=ref('md')
const disabled=ref(false)
const saved=ref(false)
const activations=ref(0)
function toggle(){if(disabled.value)return;saved.value=!saved.value;activations.value++}
function reset(){variant.value='primary';size.value='md';disabled.value=false;saved.value=false;activations.value=0}
</script>
<template>
<section class="icon-demo" aria-label="Icon button example"><div class="icon-controls"><label>Visual variant<select v-model="variant"><option v-for="v in ['primary','secondary','ghost','line','danger']" :key="v">{{ v }}</option></select></label><label>Control size<select v-model="size"><option value="sm">Small (44px)</option><option value="md">Medium (48px)</option><option value="lg">Large (56px)</option></select></label><label class="icon-disable"><input v-model="disabled" type="checkbox"> Disable example action</label></div><p>Toggle a fictitious saved item locally. The color changes presentation, not the action or its name.</p><div class="icon-stage"><button type="button" class="icon-action" :class="[variant,size,{saved}]" :disabled="disabled" aria-label="Save example item" :aria-pressed="saved" title="Save example item" @click="toggle"><i class="fa-bookmark" :class="saved?'fa-solid':'fa-regular'" aria-hidden="true"></i></button><span>Action: Save example item</span></div><p role="status" aria-atomic="true">{{ saved?'Saved locally':'Not saved' }}. Accepted activations: {{ activations }}. {{ disabled?'Action disabled.':'Action available.' }}</p><button type="button" class="icon-reset" @click="reset">Reset example</button><p>No account, file or server is changed. Danger styling does not turn this action into Delete.</p></section>
</template>
<style scoped>
